const now = new Date();
const isFirstMonday = now.getUTCDate() <= 7;
const reportMonthDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const reportMonth = `${reportMonthDate.getUTCFullYear()}-${String(reportMonthDate.getUTCMonth() + 1).padStart(2, '0')}`;
const reportMonthLabel = reportMonthDate.toLocaleDateString('en-AU', { month: 'long', year: 'numeric', timeZone: 'UTC' });
return [{ json: { isFirstMonday, reportMonth, reportMonthLabel, checkedAt: now.toISOString() } }];
